-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_PRODUCT_TERMS
--   anchor      : HUB_PRODUCT
--   grain       : SCD2 (data_7.js sats[].hist)
--   child key   : (none declared)
--   feeders     : 2 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_PRODUCT_BK__K1)) as HUB_PRODUCT_HK,
        MIN_AGE as MINIMUM_ENTRY_AGE,
        MAX_AGE as MAXIMUM_ENTRY_AGE,
        'MAXI_HLTH_UWR_VW_DATA_BASIC_DETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_bd_apv') }}
    where HUB_PRODUCT_K1__EMIT
    union all
    select
        md5(upper(HUB_PRODUCT_BK__K0)) as HUB_PRODUCT_HK,
        MINIMUM_AGE as MINIMUM_ENTRY_AGE,
        MAXIMUM_AGE as MAXIMUM_ENTRY_AGE,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_BENEFITS_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_benefits_attr_pv') }}
    where HUB_PRODUCT_K0__EMIT
)), hashed as (select *,
        case when MINIMUM_ENTRY_AGE is not null or MAXIMUM_ENTRY_AGE is not null
             then md5(upper(coalesce(MINIMUM_ENTRY_AGE::varchar,'') || '||' || coalesce(MAXIMUM_ENTRY_AGE::varchar,'')))
        end as SAT_PRODUCT_TERMS_HASHDIFF
    from feeders)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_TERMS_HASHDIFF is not null
